//! UI translations keyed by the English text: `tr("Play")` returns the current language's
//! version, or the text unchanged. `app/i18n/<locale>.json` is generated by `tools/gen_i18n.py`
//! from Feishin's locale files plus `app/i18n/listen/<locale>.json`.
//! The language is read once at start-up (changing it needs a restart).

use std::collections::HashMap;
use std::sync::RwLock;

/// The UI languages: (code, name in its own language).
pub const LANGUAGES: &[(&str, &str)] = &[
    ("en", "English"),
    ("ar", "العربية"),
    ("bn", "বাংলা"),
    ("de", "Deutsch"),
    ("es", "Español"),
    ("fr", "Français"),
    ("hi", "हिन्दी"),
    ("it", "Italiano"),
    ("ko", "한국어"),
    ("nl", "Nederlands"),
    ("pl", "Polski"),
    ("pt", "Português"),
    ("ro", "Română"),
    ("ru", "Русский"),
    ("uk", "Українська"),
    ("ur", "اردو"),
    ("zh-Hans", "简体中文"),
];

/// The language the AI DJ speaks: its own setting (a code), else the app's language.
pub fn dj_language(setting: &str) -> &str {
    match setting.trim() {
        "" => language(),
        code => code,
    }
}

/// The English name of a language code, for the AI DJ's prompt.
pub fn english_name(code: &str) -> &'static str {
    match code {
        "ar" => "Arabic",
        "bn" => "Bengali",
        "de" => "German",
        "es" => "Spanish",
        "fr" => "French",
        "hi" => "Hindi",
        "it" => "Italian",
        "ko" => "Korean",
        "nl" => "Dutch",
        "pl" => "Polish",
        "pt" => "Portuguese",
        "ro" => "Romanian",
        "ru" => "Russian",
        "uk" => "Ukrainian",
        "ur" => "Urdu",
        "zh-Hans" => "Simplified Chinese",
        _ => "English",
    }
}

struct Table {
    code: &'static str,
    map: HashMap<&'static str, &'static str>,
    /// Entries with `{}` holes ("Added {} songs"), matched against built texts.
    templates: Vec<Template>,
}

struct Template {
    /// The English text split at its holes.
    english: Vec<&'static str>,
    /// The translation split at its holes (at most as many holes; the first ones are filled).
    translated: Vec<&'static str>,
}

impl Template {
    /// The translation of `s` if it is this template with the holes filled in.
    fn apply(&self, s: &str) -> Option<String> {
        let segs = &self.english;
        let (first, last) = (segs.first()?, segs.last()?);
        let mut rest = s.strip_prefix(first)?;
        let end = rest.len().checked_sub(last.len())?;
        if !rest.is_char_boundary(end) || &rest[end..] != *last || segs.len() < 2 {
            return None;
        }
        rest = &rest[..end];
        let mut holes: Vec<&str> = Vec::new();
        for seg in &segs[1..segs.len() - 1] {
            let at = if seg.is_empty() { rest.len().min(1) } else { rest.find(seg)? };
            holes.push(&rest[..at]);
            rest = &rest[at + seg.len()..];
        }
        holes.push(rest);
        if self.translated.len() > holes.len() + 1 {
            return None;
        }
        // A short template ("{} songs") would also hit user text ("Love songs"): its holes
        // must then be numbers.
        let fixed: usize = segs.iter().map(|s| s.len()).sum();
        if fixed < 16 && !holes.iter().all(|h| h.chars().all(|c| c.is_ascii_digit() || " .,:/+-".contains(c)))
        {
            return None;
        }
        let mut out = String::from(self.translated[0]);
        for (hole, seg) in holes.iter().zip(&self.translated[1..]) {
            // "12 songs" inside a longer text is a counted noun of its own.
            match hole.starts_with(|c: char| c.is_ascii_digit()).then(|| lookup(hole)).flatten() {
                Some(t) => out.push_str(&t),
                None => out.push_str(hole),
            }
            out.push_str(seg);
        }
        Some(out)
    }
}

static CURRENT: RwLock<Option<Table>> = RwLock::new(None);

/// Development aid: with `LISTEN_I18N_COLLECT=<file>` and a non-English language, every
/// text that has no translation is appended (once) to the file, to find what to translate.
static COLLECT: std::sync::Mutex<Option<(std::path::PathBuf, std::collections::HashSet<String>)>> =
    std::sync::Mutex::new(None);

static COLLECTING: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

fn collect_miss(s: &str) {
    if !COLLECTING.load(std::sync::atomic::Ordering::Relaxed) {
        return;
    }
    let mut guard = COLLECT.lock().unwrap_or_else(|e| e.into_inner());
    if let Some((path, seen)) = guard.as_mut()
        && s.chars().any(|c| c.is_alphabetic())
        && seen.insert(s.to_string())
    {
        use std::io::Write;
        if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true).open(path) {
            let _ = writeln!(f, "{}", serde_json::to_string(s).unwrap_or_default());
        }
    }
}

fn source(code: &str) -> Option<&'static str> {
    match code {
        "ar" => Some(include_str!("../i18n/ar.json")),
        "bn" => Some(include_str!("../i18n/bn.json")),
        "de" => Some(include_str!("../i18n/de.json")),
        "es" => Some(include_str!("../i18n/es.json")),
        "fr" => Some(include_str!("../i18n/fr.json")),
        "hi" => Some(include_str!("../i18n/hi.json")),
        "it" => Some(include_str!("../i18n/it.json")),
        "ko" => Some(include_str!("../i18n/ko.json")),
        "nl" => Some(include_str!("../i18n/nl.json")),
        "pl" => Some(include_str!("../i18n/pl.json")),
        "pt" => Some(include_str!("../i18n/pt.json")),
        "ro" => Some(include_str!("../i18n/ro.json")),
        "ru" => Some(include_str!("../i18n/ru.json")),
        "uk" => Some(include_str!("../i18n/uk.json")),
        "ur" => Some(include_str!("../i18n/ur.json")),
        "zh-Hans" => Some(include_str!("../i18n/zh-Hans.json")),
        _ => None,
    }
}

/// `LANG`-style value (`de_DE.UTF-8`, `pt_BR`, `zh_TW`) -> the nearest supported code.
pub fn from_locale(value: &str) -> &'static str {
    let base = value.split(['.', '@']).next().unwrap_or("");
    let norm = base.replace('_', "-");
    let (lang, region) = norm.split_once('-').unwrap_or((norm.as_str(), ""));
    let lang = lang.to_lowercase();
    let found = |code: &str| LANGUAGES.iter().find(|(c, _)| *c == code).map(|(c, _)| *c);
    match (lang.as_str(), region.to_uppercase().as_str()) {
        ("zh", _) => Some("zh-Hans"),
        (l, _) => found(l),
    }
    .unwrap_or("en")
}

/// The code for the `language` setting: `""` follows the system locale.
pub fn resolve(setting: &str) -> &'static str {
    if let Some((code, _)) = LANGUAGES.iter().find(|(c, _)| *c == setting) {
        return code;
    }
    for var in ["LC_ALL", "LC_MESSAGES", "LANG"] {
        if let Ok(v) = std::env::var(var)
            && !v.is_empty()
            && v != "C"
            && v != "POSIX"
        {
            return from_locale(&v);
        }
    }
    "en"
}

/// Makes `code` (a supported code, see [`resolve`]) the language of [`tr`].
pub fn set_language(code: &str) {
    let code = LANGUAGES.iter().find(|(c, _)| *c == code).map_or("en", |(c, _)| *c);
    let mut map = HashMap::new();
    let mut templates = Vec::new();
    if let Some(json) = source(code)
        && let Ok(parsed) = serde_json::from_str::<HashMap<String, String>>(json)
    {
        for (k, v) in parsed {
            // Leaked once per start-up so lookups can return `&'static str`.
            let (k, v): (&'static str, &'static str) =
                (Box::leak(k.into_boxed_str()), Box::leak(v.into_boxed_str()));
            if k.contains("{}") && k.matches("{}").count() >= v.matches("{}").count() {
                templates
                    .push(Template { english: k.split("{}").collect(), translated: v.split("{}").collect() });
            } else {
                map.insert(k, v);
            }
        }
    }
    if let Ok(path) = std::env::var("LISTEN_I18N_COLLECT") {
        *COLLECT.lock().unwrap_or_else(|e| e.into_inner()) = Some((path.into(), Default::default()));
        COLLECTING.store(true, std::sync::atomic::Ordering::Relaxed);
    }
    *CURRENT.write().unwrap_or_else(|e| e.into_inner()) = Some(Table { code, map, templates });
}

/// The active language code (`en` before [`set_language`]).
pub fn language() -> &'static str {
    CURRENT.read().ok().and_then(|t| t.as_ref().map(|t| t.code)).unwrap_or("en")
}

fn lookup(s: &str) -> Option<std::borrow::Cow<'static, str>> {
    use std::borrow::Cow;
    let guard = CURRENT.read().unwrap_or_else(|e| e.into_inner());
    let table = guard.as_ref().filter(|t| t.code != "en")?;
    let hit = table
        .map
        .get(s)
        .map(|t| Cow::Borrowed(*t))
        .or_else(|| table.templates.iter().find_map(|t| t.apply(s)).map(Cow::Owned));
    if hit.is_none() {
        collect_miss(s);
    }
    hit
}

/// The translation of the English text `s`; `s` itself when there is none. Texts built
/// with `format!` only translate through [`tr_cow`] (they need an owned result).
pub fn tr(s: &str) -> &str {
    let guard = CURRENT.read().unwrap_or_else(|e| e.into_inner());
    match guard.as_ref() {
        Some(t) if t.code != "en" => t.map.get(s).copied().unwrap_or(s),
        _ => s,
    }
}

/// [`tr`] for the owned/borrowed strings iced text takes; also fills templates.
pub fn tr_cow(s: std::borrow::Cow<'_, str>) -> std::borrow::Cow<'_, str> {
    match lookup(&s) {
        Some(t) => t,
        None => s,
    }
}

/// [`tr`] with `{}` placeholders filled in order: `trf("Added {} songs", &[&n])`.
pub fn trf(pattern: &str, args: &[&dyn std::fmt::Display]) -> String {
    let mut out = String::new();
    let mut args = args.iter();
    let mut rest = tr(pattern);
    while let Some(i) = rest.find("{}") {
        out.push_str(&rest[..i]);
        if let Some(a) = args.next() {
            out.push_str(&a.to_string());
        }
        rest = &rest[i + 2..];
    }
    out.push_str(rest);
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn locale_names_map_to_codes() {
        assert_eq!(from_locale("de_DE.UTF-8"), "de");
        assert_eq!(from_locale("pt_BR.UTF-8"), "pt");
        assert_eq!(from_locale("pt_PT"), "pt");
        assert_eq!(from_locale("zh_CN"), "zh-Hans");
        assert_eq!(from_locale("ja_JP.UTF-8"), "en");
        assert_eq!(from_locale("xx_YY"), "en");
        assert_eq!(from_locale("C"), "en");
        assert_eq!(resolve("fr"), "fr");
    }

    #[test]
    fn every_language_has_a_table_that_parses() {
        assert_eq!(LANGUAGES.len(), 17);
        for (code, _) in LANGUAGES.iter().filter(|(c, _)| *c != "en") {
            let json = source(code).unwrap_or_else(|| panic!("{code} missing"));
            let map: HashMap<String, String> = serde_json::from_str(json).unwrap();
            assert!(map.len() > 1000, "{code}: {}", map.len());
        }
    }

    #[test]
    fn placeholders_fill_in_order() {
        // English (and any text without a table entry) passes through.
        assert_eq!(trf("{} of {}", &[&1, &2]), "1 of 2");
    }
}
